/** A holiday on the sheet (yyyy-mm-dd). A claim's due-by, fixed when it is added, is moved past those
 *  on the sheet then. */
export type Holiday = { date: string };

/** Under the sheet's key, so loading the sheet again re-reads its holidays. */
